files={"cloudflare_transport.py":""""Private Cloudflare Worker Bot API relay transport.

Does not require Telegram api_id/api_hash or local access to api.telegram.org.
Only user-owned Cloudflare Workers HTTPS endpoint accepted.
"""
import json, urllib.request, urllib.error, urllib.parse, socket

class RelayError(Exception): pass

def check_url(value):
    raw=str(value or "").strip().rstrip("/")
    u=urllib.parse.urlsplit(raw)
    if u.scheme!="https" or not u.hostname or u.username or u.password or u.port not in (None,443) or u.query or u.fragment or u.path not in ("","/"):
        raise RelayError("cloudflare_worker_https_origin_required")
    if not u.hostname.endswith(".workers.dev"):
        raise RelayError("only_owner_workers_dev_allowed")
    return raw

def rpc(worker_url,relay_key,method,params,timeout=18):
    base=check_url(worker_url)
    if not relay_key or len(relay_key)<48:raise RelayError("relay_key_must_be_48_chars")
    if method not in ("getMe","getWebhookInfo","getUpdates","sendMessage"):
        raise RelayError("method_not_allowed")
    payload=json.dumps({"method":method,"params":params or {}},ensure_ascii=False,separators=(",",":")).encode("utf8")
    req=urllib.request.Request(base+"/rpc",data=payload,method="POST",
        headers={"Content-Type":"application/json","X-Curator-Relay-Key":relay_key})
    try:
        with urllib.request.build_opener(urllib.request.ProxyHandler({})).open(req,timeout=timeout) as res:
            result=json.loads(res.read(2000000).decode("utf8"))
    except urllib.error.HTTPError as e:
        raise RelayError("worker_http_"+str(e.code)) from None
    except (OSError,ValueError):
        raise RelayError("worker_network_or_response_error") from None
    if not isinstance(result,dict):raise RelayError("worker_nonobject_result")
    if result.get("ok") is not True:
        raise RelayError("telegram_api_rejected_code_"+str(result.get("error_code") or 0))
    return result.get("result")
","setup_cloudflare.py":""""Local-only owner pairing with personal Cloudflare Worker; NO Telegram MTProto app ID/hash.
Requires owner's Cloudflare Worker secrets TELEGRAM_BOT_TOKEN, CURATOR_RELAY_KEY.
"""
import getpass, os, secrets, sys, time, pathlib
from cloudflare_transport import rpc, check_url, RelayError
from secrets_store import write as dpapi_write, SecretError
from daemon import exact_curator, Blocked
from mtproto_common import make_bridge_config

BASE=pathlib.Path(os.environ.get("LOCALAPPDATA") or str(pathlib.Path.home()))/"Neur0StoreCurator"
CREDS=BASE/"cloudflare_credentials.dpapi"

def main():
    if os.name!="nt" or not sys.stdin.isatty():
        raise RelayError("interactive_local_Windows_required")
    if CREDS.exists():raise RelayError("cloudflare_creds_already_exist_do_not_overwrite")
    print("Telegram Bot API through YOUR Cloudflare Worker — no api_id or api_hash.")
    print("Revoke previously published bot token via @BotFather /revoke.")
    print("Create Cloudflare Worker with worker.js; in its Secrets add TELEGRAM_BOT_TOKEN and CURATOR_RELAY_KEY.")
    print("Do NOT copy bot token or worker secret into ChatGPT/GitHub.")
    if input("Type ROTATED once old BotFather token is revoked: ").strip()!="ROTATED":
        raise RelayError("rotation_not_confirmed")
    exact_curator(make_bridge_config({"chatid":0,"userid":0}))
    url=check_url(input("Your Worker HTTPS origin (https://your-worker.username.workers.dev): ").strip())
    key=getpass.getpass("CURATOR_RELAY_KEY matching your private Cloudflare Worker Secret (hidden): ").strip()
    if len(key)<48:raise RelayError("private_relay_key_too_short")
    me=rpc(url,key,"getMe",{})
    if not isinstance(me,dict) or str(me.get("username","")).casefold()!="neur0store_bot" or not me.get("is_bot"):
        raise RelayError("wrong_bot_account")
    wh=rpc(url,key,"getWebhookInfo",{})
    if (wh or {}).get("url"):raise RelayError("bot_has_existing_webhook_refuse_consumer_takeover")
    code=secrets.token_hex(5).upper()
    print("Send in private @Neur0Store_bot: /start "+code)
    offset=None
    expiry=time.monotonic()+150
    while time.monotonic()<expiry:
        params={"timeout":6,"limit":50,"allowed_updates":["message"]}
        if offset is not None:params["offset"]=offset
        updates=rpc(url,key,"getUpdates",params,timeout=13)
        if not isinstance(updates,list):raise RelayError("updates_response_invalid")
        for entry in updates:
            uid=entry.get("update_id")
            if not isinstance(uid,int):continue
            offset=max(offset or 0,uid+1)
            msg=entry.get("message") or {}
            frm=msg.get("from") or {}
            ch=msg.get("chat") or {}
            if (msg.get("text") or "").strip()=="/start "+code and ch.get("type")=="private" and \
                isinstance(frm.get("id"),int) and frm.get("id")==ch.get("id") and not frm.get("is_bot"):
                BASE.mkdir(parents=True,exist_ok=True)
                dpapi_write({"worker_url":url,"relay_key":key,"chatid":frm["id"],"userid":frm["id"],
                    "offset":offset},CREDS)
                print("OWNER_PAIRED; worker identity verified; secrets encrypted with Windows DPAPI")
                return
    raise RelayError("private_start_pairing_timeout")

if __name__=="__main__":
    try:main()
    except (RelayError,Blocked,SecretError) as e:
        print("SETUP_BLOCKED:"+str(e),file=sys.stderr);sys.exit(2)
","cloudflare_gateway.py":""""Private owner polling through Cloudflare Worker to exact curator Bridge.
No Telegram app api_id/hash and no direct api.telegram.org connectivity needed.
