import os,sys,sqlite3,time,pathlib
from secrets_store import read as dpapi_read, SecretError
from cloudflare_transport import rpc,RelayError
import daemon

BASE=pathlib.Path(os.environ.get("LOCALAPPDATA") or str(pathlib.Path.home()))/"Neur0StoreCurator"
CREDS=BASE/"cloudflare_credentials.dpapi"
DB=BASE/"cloudflare_inbox.sqlite3"
def config():
    if not CREDS.exists():raise RelayError("run_SETUP_CLOUDFLARE_cmd_first")
    saved=dpapi_read(CREDS)
    if not isinstance(saved,dict) or not (saved.get("userid") and saved.get("chatid")):
        raise RelayError("owner_binding_missing")
    c={
      "chatid":int(saved["chatid"]),"userid":int(saved["userid"]),
      "base":"http://127.0.0.1:17448","db":str(DB),
      "CURATOR_MANAGED_CHAT_ID":"tg-curator-owner",
      "CURATOR_CHAT_URL":"https://chatgpt.com/c/6ac7068e-883c-83ed-9081-cb94557e61bd",
      "CURATOR_REPOSITORY":"foto6/boss",
      "CURATOR_BRANCH":"agent/telegram-curator-authority-20261012",
      "CURATOR_EXPECTED_HEAD":"773b42f59018a2e55834b87275796486d686e4f6",
      "_worker_url":saved["worker_url"],"_worker_key":saved["relay_key"],
      "_offset_init":int(saved.get("offset",0))
    }
    if c["userid"] != c["chatid"] or c["chatid"]<=0:
        raise RelayError("private_owner_binding_invalid")
    return c

def api(c,m,p):
    return rpc(c["_worker_url"],c["_worker_key"],m,p,timeout=17)

def notify(c,text,reply_id=0):
    params={"chat_id":c["chatid"],"text":str(text)[:3800]}
    if reply_id:params["reply_parameters"]={"message_id":int(reply_id),"allow_sending_without_reply":True}
    return api(c,"sendMessage",params)

def init_offset(db,c):
    with db:
        row=db.execute("SELECT v FROM meta WHERE k='offset'").fetchone()
        if row is None:
            db.execute("INSERT INTO meta(k,v) VALUES('offset',?)",(str(c["_offset_init"]),))

def main():
    c=config()
    daemon.exact_curator(c)
    me=api(c,"getMe",{})
    if str(me.get("username","")).casefold()!="neur0store_bot" or not me.get("is_bot"):
        raise RelayError("cloudflare_worker_wrong_bot")
    db=daemon.open_db(c)
    try:
        init_offset(db,c)
        print("CLOUDFLARE_GATEWAY_READY; owner only; durable SQLite; Cloudflare Worker HTTPS Bot API")
        while True:
            try:
                updates=api(c,"getUpdates",{"offset":daemon.offset(db),"timeout":6,
                                         "allowed_updates":["message"],"limit":30})
                for update in updates:
                    daemon.receive(db,c,update,notify_fn=notify)
                daemon.deliver(db,c,notify_fn=notify)
            except KeyboardInterrupt:
                return
            except (daemon.Blocked,RelayError,TimeoutError) as e:
                print("GATEWAY_NETWORK_OR_BRIDGE_GATE:"+type(e).__name__,file=sys.stderr)
                time.sleep(5)
    finally:db.close()

if __name__=="__main__":
    try:main()
    except (daemon.Blocked,RelayError,SecretError) as e:
        print("CLOUDFLARE_GATEWAY_BLOCKED:"+str(e),file=sys.stderr);sys.exit(2)
